/** static bool8 ListMenuChangeSelection(struct ListMenu *list, bool8 updateCursorAndCallCallback, u8 count, bool8 movingDown) */
export function ListMenuChangeSelection(list: any, updateCursorAndCallCallback: any, count: any, movingDown: any): any {
  let oldSelectedRow: any = null;
      let selectionChange, i, cursorCount;

      oldSelectedRow = list.selectedRow;
      cursorCount = 0;
      selectionChange = 0;
      for (i = 0; i < count; i++)
      {
          do
          {
              let ret: any = ListMenuUpdateSelectedRowIndexAndScrollOffset(list, movingDown);
              selectionChange |= ret;
              if (ret != 2)
                  break;
              cursorCount++;
          } while (list.template.items[list.scrollOffset + list.selectedRow].id == LIST_HEADER);
      }

      if (updateCursorAndCallCallback)
      {
          switch (selectionChange)
          {
          case 0:
          default:
              return TRUE;
          case 1:
              ListMenuErasePrintedCursor(list, oldSelectedRow);
              ListMenuDrawCursor(list);
              ListMenuCallSelectionChangedCallback(list, FALSE);
              CopyWindowToVram(list.template.windowId, COPYWIN_GFX);
              break;
          case 2:
          case 3:
              ListMenuErasePrintedCursor(list, oldSelectedRow);
              ListMenuScroll(list, cursorCount, movingDown);
              ListMenuDrawCursor(list);
              ListMenuCallSelectionChangedCallback(list, FALSE);
              CopyWindowToVram(list.template.windowId, COPYWIN_GFX);
              break;
          }
      }

      return FALSE;
}

